const AWS = require('aws-sdk');
const express = require('express');
const app = express();

// Utility: deep merge for configuration objects
function deepMerge(target, source) {
  for (const key in source) {
    if (source.hasOwnProperty(key)) {
      if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
        if (!target[key]) target[key] = {};
        deepMerge(target[key], source[key]);
      } else {
        target[key] = source[key];
      }
    }
  }
  return target;
}

// Default workflow configuration
const defaultConfig = {
  stateMachine: {
    arn: process.env.STATE_MACHINE_ARN,
    region: 'us-east-1'
  },
  execution: {
    timeout: 300,
    retryOnError: true
  },
  logging: {
    level: 'info',
    destination: 'cloudwatch'
  }
};

// Start Step Functions execution with user-provided overrides
app.post('/api/workflow/start', express.json(), async (req, res) => {
  try {
    const userConfig = req.body.config || {};

    // Merge user config with defaults - allows customization of execution params
    const mergedConfig = deepMerge({}, defaultConfig);
    deepMerge(mergedConfig, userConfig);

    const stepfunctions = new AWS.StepFunctions({
      region: mergedConfig.stateMachine.region,
      endpoint: process.env.SFN_ENDPOINT || undefined
    });

    const params = {
      stateMachineArn: mergedConfig.stateMachine.arn,
      input: JSON.stringify({
        payload: req.body.payload,
        metadata: {
          requestId: req.headers['x-request-id'],
          timestamp: Date.now(),
          timeout: mergedConfig.execution.timeout
        }
      })
    };

    const result = await stepfunctions.startExecution(params).promise();

    res.json({
      executionArn: result.executionArn,
      startDate: result.startDate,
      config: {
        timeout: mergedConfig.execution.timeout,
        region: mergedConfig.stateMachine.region
      }
    });
  } catch (error) {
    console.error('Workflow start failed:', error.message);
    res.status(500).json({ error: 'Failed to start workflow' });
  }
});

// Get execution status
app.get('/api/workflow/status/:executionArn', async (req, res) => {
  try {
    const stepfunctions = new AWS.StepFunctions({
      region: process.env.AWS_REGION || 'us-east-1',
      endpoint: process.env.SFN_ENDPOINT || undefined
    });

    const result = await stepfunctions.describeExecution({
      executionArn: decodeURIComponent(req.params.executionArn)
    }).promise();

    res.json(result);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Health check with config introspection
app.get('/api/health', (req, res) => {
  const config = deepMerge({}, defaultConfig);
  res.json({
    status: 'healthy',
    version: process.env.APP_VERSION || '1.0.0',
    constructor: config.constructor?.name,
    hasProto: Object.getPrototypeOf(config) === Object.prototype
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Workflow service listening on ${PORT}`));
